async def main(args):
    files = args.params.get("changed_files") or []
    paths = []
    for f in files:
        paths.append(str(f.get("file") if isinstance(f, dict) else f))
    NODE_DIRS = {"nodes", "nodes_builtin"}          # 目录段名（.agent/nodes/x.py 的 parts 含 "nodes"）
    TOOL_DIRS = {"tools", "tools_builtin"}
    hits_node, hits_tool, hits_engine = [], [], []
    for p in paths:
        parts = [s for s in p.replace("\\", "/").split("/") if s]
        if not parts:
            continue
        segs = set(parts)
        if parts[-1].endswith((".py", ".js")):
            if segs & NODE_DIRS:
                hits_node.append(p)
            elif segs & TOOL_DIRS:
                hits_tool.append(p)
        if parts[0] == "src" and not (segs & (NODE_DIRS | TOOL_DIRS)) and parts[-1].endswith(".py"):
            hits_engine.append(p)   # 引擎源码（非插件目录）：reload 不够，需重启
    scope = "none"
    if hits_node and hits_tool:
        scope = "all"
    elif hits_node:
        scope = "nodes"
    elif hits_tool:
        scope = "tools"
    note = ""
    if hits_engine:
        note = "；⚠️ 引擎源码改动（" + ", ".join(hits_engine[:3]) + "）需 /restart 生效"
    return {"need": scope != "none", "scope": scope,
            "summary": f"改动命中：节点 {[f.split('/')[-1] for f in hits_node]} / 工具 {[f.split('/')[-1] for f in hits_tool]}{note}"}
